selector_to_html = {"a[href=\"#nvidia-flaggems\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u5728\u975e\u82f1\u4f1f\u8fbe\uff08NVIDIA\uff09\u786c\u4ef6\u4e0a\u4f7f\u7528 FlagGems<a class=\"headerlink\" href=\"#nvidia-flaggems\" title=\"Link to this heading\">#</a></h1><h2>1. \u652f\u6301\u7684\u5e73\u53f0<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><p><em>FlagGems</em> \u5728 NVIDIA \u82af\u7247\u4e4b\u5916\u652f\u6301\u82e5\u5e72\u4e0d\u540c\u7c7b\u578b\u7684 AI \u82af\u7247\u6216\u5e73\u53f0\u3002\n\u8bf7\u53c2\u9605<a class=\"reference internal\" href=\"../overview/platforms.html\"><span class=\"doc std std-doc\">\u5e73\u53f0\u652f\u6301</span></a>\n\u6587\u6863\u4e86\u89e3\u5df2\u7ecf\u9a8c\u8bc1\u8fc7\u7684\u5e73\u53f0\u7684\u6700\u65b0\u5217\u8868\u3002</p>", "a[href=\"../overview/platforms.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u652f\u6301\u7684\u786c\u4ef6\u5e73\u53f0<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p><em>FlagGems</em> \u652f\u6301\u8d85\u8fc7 10 \u79cd\u4e0d\u540c\u540e\u7aef\u786c\u4ef6\u5e73\u53f0\u3002\u76ee\u524d\u652f\u6301\u7684\u5e73\u53f0\u53ca\u8fd9\u4e9b\u5e73\u53f0\u7684\u80fd\u529b\u5217\u4e3e\u5982\u4e0b\uff1a</p>", "a[href=\"#id4\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">4. \u540e\u7aef\u81ea\u52a8\u68c0\u6d4b\u4e0e\u624b\u52a8\u8bbe\u7f6e<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h2><p>\u9ed8\u8ba4\u60c5\u51b5\u4e0b\uff0c<em>FlagGems</em> \u80fd\u591f\u5728\u8fd0\u884c\u65f6\u81ea\u52a8\u68c0\u6d4b\u5f53\u524d\u4f7f\u7528\u7684\u786c\u4ef6\u540e\u7aef\uff0c\u4e3a\u4e4b\u9009\u62e9\u5bf9\u5e94\u7684\u7b97\u5b50\u5b9e\u73b0\u3002\n\u5f88\u591a\u65f6\u5019\uff0c\u6240\u6709\u7684\u7ec4\u4ef6\u90fd\u80fd\u591f\u76f4\u63a5\u5de5\u4f5c\uff0c\u4e0d\u9700\u8981\u624b\u52a8\u7684\u914d\u7f6e\u3002</p><p>\u5982\u679c\u5185\u7f6e\u7684\u81ea\u52a8\u540e\u7aef\u68c0\u6d4b\u673a\u5236\u5931\u8d25\uff0c\u6216\u8005\u5728\u4f60\u7684\u73af\u5883\u4e2d\u51fa\u73b0\u4e86\u517c\u5bb9\u6027\u76f8\u5173\u7684\u95ee\u9898\uff0c\n\u4f60\u53ef\u4ee5\u624b\u52a8\u8bbe\u7f6e\u76ee\u6807\u540e\u7aef\uff0c\u4ee5\u786e\u4fdd\u8fd0\u884c\u65f6\u7b97\u5b50\u7684\u884c\u4e3a\u662f\u6b63\u786e\u7684\u3002\n\u4f60\u53ef\u4ee5\u901a\u8fc7\u8bbe\u7f6e\u4e0b\u9762\u7684\u73af\u5883\u53d8\u91cf\u6765\u6307\u5b9a\u540e\u7aef\uff0c\u4e4b\u540e\u518d\u8fd0\u884c\u4f60\u7684\u4ee3\u7801\uff1a</p>", "a[href=\"#id2\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. \u7edf\u4e00\u7684\u4f7f\u7528\u63a5\u53e3<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2><p>\u65e0\u8bba\u4e0b\u5c42\u4f7f\u7528\u7684\u662f\u54ea\u79cd\u786c\u4ef6\uff0c<code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems</span></code> \u7684\u7528\u6cd5\u59cb\u7ec8\u4fdd\u6301\u4e0d\u53d8\u3002\n\u4ece NVIDIA \u5e73\u53f0\u5207\u6362\u5230\u975e NVIDIA \u5e73\u53f0\u65f6\uff0c\u4e00\u822c\u800c\u8a00\u4e0d\u9700\u8981\u66f4\u6539\u5e94\u7528\u4ee3\u7801\u3002</p><p>\u5f53\u4f60\u5728\u4ee3\u7801\u4e2d\u5bfc\u5165\u4e86 <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems</span></code> \u5305\uff0c\u5e76\u4e14\n<a class=\"reference internal\" href=\"#../basic/#enabling-flaggems\"><span class=\"xref myst\">\u542f\u7528\u4e86 <em>FlagGems</em> \u52a0\u901f</span></a>\u4e4b\u540e\uff0c\n\u7b97\u5b50\u7684\u6d3e\u53d1\u673a\u5236\u4f1a\u81ea\u52a8\u5c06\u5bf9\u7b97\u5b50\u7684\u8c03\u7528\u6307\u5411\u9488\u5bf9\u5f53\u524d\u540e\u7aef\u7684\u6b63\u786e\u5b9e\u73b0\u4e0a\u3002\n\u8fd9\u4e00\u6d3e\u53d1\u673a\u5236\u4e3a\u5f00\u53d1\u8005\u63d0\u4f9b\u4e86\u8de8\u4e0d\u540c\u73af\u5883\u7684\u4f53\u9a8c\u4e00\u81f4\u6027\u3002</p>", "a[href=\"#id3\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. \u5e73\u53f0\u9700\u6c42<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h2><p>\u5c3d\u7ba1 <em>FlagGems</em> \u7684\u4f7f\u7528\u6a21\u5f0f\u4fdd\u6301\u4e0d\u53d8\uff0c\u5728\u975e NVIDIA \u5e73\u53f0\u4e0a\u8fd0\u884c <em>FlagGems</em>\n\u65f6\u4ecd\u7136\u9700\u8981\u6ee1\u8db3\u4e00\u4e9b\u524d\u7f6e\u6761\u4ef6\u3002\u4f60\u5fc5\u987b\u5728\u76ee\u6807\u5e73\u53f0\u4e0a\u5b89\u88c5\u4e86 <em>PyTorch</em> \u548c <em>Triton</em>\n\u7f16\u8bd1\u5668\u3002</p><p>\u901a\u5e38\u800c\u8a00\uff0c\u6709\u4e24\u79cd\u65b9\u5f0f\u53ef\u4ee5\u5b9e\u73b0\u517c\u5bb9\u7684\u8f6f\u4ef6\u6784\u5efa\uff1a</p>", "a[href=\"#id1\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. \u652f\u6301\u7684\u5e73\u53f0<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><p><em>FlagGems</em> \u5728 NVIDIA \u82af\u7247\u4e4b\u5916\u652f\u6301\u82e5\u5e72\u4e0d\u540c\u7c7b\u578b\u7684 AI \u82af\u7247\u6216\u5e73\u53f0\u3002\n\u8bf7\u53c2\u9605<a class=\"reference internal\" href=\"../overview/platforms.html\"><span class=\"doc std std-doc\">\u5e73\u53f0\u652f\u6301</span></a>\n\u6587\u6863\u4e86\u89e3\u5df2\u7ecf\u9a8c\u8bc1\u8fc7\u7684\u5e73\u53f0\u7684\u6700\u65b0\u5217\u8868\u3002</p>"}
